sp_widget.client_script:
api.controller = function($scope, $location) {

    var c = this;


    // ==========================================
    // BACK TO APPLICATIONS
    // ==========================================

    c.goBack = function() {

        window.location.href =
            '?id=campus360_recruiter_applications_new';

    };

};

sp_widget.css:
.student-profile-page {
    max-width: 1100px;
    margin: 0 auto;
    padding: 24px;
    color: #102a5c;
}


/* =========================================
   HEADER
========================================= */

.profile-header {
    background: #ffffff;
    border: 1px solid #dce3f2;
    border-radius: 18px;
    padding: 32px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 24px;
    box-shadow: 0 8px 25px rgba(30, 60, 100, 0.06);
}

.profile-header h1 {
    margin: 8px 0;
    font-size: 28px;
    font-weight: 700;
}

.profile-header p {
    margin: 0 0 14px;
    color: #60739a;
    font-size: 13px;
}

.eyebrow {
    font-size: 10px;
    letter-spacing: 2px;
    font-weight: 700;
    color: #5367e8;
}

.company-info {
    display: inline-block;
    padding: 8px 12px;
    border-radius: 7px;
    background: #f0f3ff;
    color: #5265d9;
    font-size: 11px;
    font-weight: 600;
}


/* =========================================
   BUTTON
========================================= */

.btn {
    border-radius: 8px;
    padding: 11px 18px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
}

.btn-secondary {
    background: #ffffff;
    color: #5367e8;
    border: 1px solid #cdd6eb;
}


/* =========================================
   PROFILE SUMMARY
========================================= */

.profile-summary {
    background: #ffffff;
    border: 1px solid #dce3f2;
    border-radius: 18px;
    padding: 28px;
    display: flex;
    align-items: center;
    gap: 20px;
    margin-bottom: 20px;
    box-shadow: 0 8px 25px rgba(30, 60, 100, 0.05);
}

.large-avatar {
    width: 70px;
    height: 70px;
    border-radius: 18px;
    background: #eef0ff;
    color: #5367e8;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 27px;
    font-weight: 700;
}

.profile-main {
    flex: 1;
}

.profile-main h2 {
    margin: 0 0 5px;
    font-size: 23px;
}

.student-id {
    margin: 0 0 10px;
    color: #7182a4;
    font-size: 12px;
}

.placement-badge {
    display: inline-block;
    background: #edf8f1;
    color: #17834c;
    border-radius: 20px;
    padding: 6px 11px;
    font-size: 11px;
    font-weight: 600;
}

.resume-btn {
    display: inline-block;
    background: #5367e8;
    color: #ffffff;
    padding: 11px 18px;
    border-radius: 8px;
    font-size: 12px;
    font-weight: 600;
    text-decoration: none;
}


/* =========================================
   PROFILE CARD
========================================= */

.profile-card {
    background: #ffffff;
    border: 1px solid #dce3f2;
    border-radius: 18px;
    margin-bottom: 20px;
    overflow: hidden;
    box-shadow: 0 8px 25px rgba(30, 60, 100, 0.05);
}

.card-header {
    padding: 22px 26px;
    border-bottom: 1px solid #e6ebf4;
}

.card-header h2 {
    margin: 0;
    font-size: 18px;
}

.card-header p {
    margin: 6px 0 0;
    font-size: 12px;
    color: #7182a4;
}


/* =========================================
   PROFILE GRID
========================================= */

.profile-grid {
    padding: 25px;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 22px 40px;
}

.profile-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.field-label {
    font-size: 11px;
    color: #7889a8;
}

.profile-field strong {
    font-size: 13px;
    color: #183467;
}


/* =========================================
   ACADEMIC
========================================= */

.academic-grid {
    padding: 25px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 15px;
}

.academic-box {
    background: #f7f9ff;
    border: 1px solid #e4e9f5;
    border-radius: 12px;
    padding: 18px;
}

.academic-box span {
    display: block;
    color: #7182a4;
    font-size: 11px;
    margin-bottom: 8px;
}

.academic-box strong {
    font-size: 20px;
    color: #183467;
}


/* =========================================
   APPLICATION HISTORY
========================================= */

.application-history {
    padding: 0 25px 20px;
}

.application-history-row {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 1fr;
    gap: 20px;
    align-items: center;
    padding: 18px 0;
    border-bottom: 1px solid #edf0f6;
}

.application-history-row:last-child {
    border-bottom: none;
}

.application-history-row strong {
    display: block;
    font-size: 13px;
}

.application-history-row span {
    font-size: 11px;
    color: #7182a4;
}

.status-badge {
    display: inline-block;
    padding: 6px 10px;
    border-radius: 20px;
    font-size: 10px;
    font-weight: 600;
}

.status-pending {
    background: #fff5df;
    color: #b97700;
}

.status-submitted {
    background: #eaf2ff;
    color: #2868c7;
}

.status-selected {
    background: #eaf8ef;
    color: #16814a;
}


/* =========================================
   ERROR
========================================= */

.error-message {
    background: #fff1f1;
    border: 1px solid #ffd1d1;
    color: #c33b3b;
    padding: 15px;
    border-radius: 10px;
    margin-bottom: 20px;
}


/* =========================================
   EMPTY
========================================= */

.empty-state {
    padding: 35px;
    text-align: center;
    color: #7182a4;
}


/* =========================================
   MOBILE
========================================= */

@media (max-width: 768px) {

    .profile-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 20px;
    }

    .profile-grid {
        grid-template-columns: 1fr;
    }

    .academic-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .profile-summary {
        flex-wrap: wrap;
    }

    .application-history-row {
        grid-template-columns: 1fr;
        gap: 8px;
    }

}

sp_widget.script:
(function() {

    // =====================================================
    // CAMPUS360 RECRUITER STUDENT PROFILE
    // =====================================================


    // =====================================================
    // CURRENT COMPANY
    // =====================================================

    var companySysId =
        'e9268662acd303107f44b432e349694b';


    // =====================================================
    // GET STUDENT SYS ID FROM URL
    // =====================================================

    var studentSysId =
        $sp.getParameter('sys_id');


    if (!studentSysId) {

        data.error =
            'Student profile could not be identified.';

        return;

    }


    // =====================================================
    // COMPANY INFORMATION
    // =====================================================

    var companyGR =
        new GlideRecord(
            'x_snc_campus360_company_master'
        );


    if (companyGR.get(companySysId)) {

        data.company_name =
            companyGR.getValue('company_name');

        data.company_id =
            companyGR.getValue('company_id');

    }


    // =====================================================
    // SECURITY CHECK
    //
    // Make sure this student has actually applied
    // to an opportunity belonging to this company.
    // =====================================================

    var applicationCheck =
        new GlideRecord(
            'x_snc_campus360_student_application'
        );


    applicationCheck.addQuery(
        'student',
        studentSysId
    );


    applicationCheck.addQuery(
        'opportunity.company',
        companySysId
    );


    applicationCheck.setLimit(1);

    applicationCheck.query();


    if (!applicationCheck.next()) {

        data.error =
            'This student profile is not available for your company.';

        return;

    }


    // =====================================================
    // GET STUDENT MASTER
    // =====================================================

    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );


    if (!studentGR.get(studentSysId)) {

        data.error =
            'Student record could not be found.';

        return;

    }


    // =====================================================
    // STUDENT BASIC INFORMATION
    // =====================================================

    data.student = {};


    data.student.sys_id =
        studentGR.getUniqueValue();


    data.student.student_name =
        studentGR.getValue('student_name');


    data.student.student_id =
        studentGR.getValue('student_id');


    data.student.email =
        studentGR.getValue('email');


    data.student.phone_number =
        studentGR.getValue('phone_number');


    data.student.batch =
        studentGR.getValue('batch');


    data.student.branch =
        studentGR.getDisplayValue('branch');


    data.student.degree =
        studentGR.getDisplayValue('degree');


    data.student.cgpa =
        studentGR.getValue('cgpa');


    data.student.backlogs =
        studentGR.getValue('backlogs');


    data.student.placement_status =
        studentGR.getDisplayValue(
            'placement_status'
        );


    // =====================================================
    // USER
    // =====================================================

    if (studentGR.user) {

        data.student.user =
            studentGR.user.getDisplayValue();

    } else {

        data.student.user = '';

    }


    // =====================================================
    // RESUME ATTACHMENT
    // =====================================================

    data.student.resume_available = false;

    data.student.resume_url = '';


    var attachmentGR =
        new GlideRecord('sys_attachment');


    attachmentGR.addQuery(
        'table_name',
        'x_snc_campus360_student_master'
    );


    attachmentGR.addQuery(
        'table_sys_id',
        studentSysId
    );


    attachmentGR.addQuery(
        'file_name',
        'STARTSWITH',
        ''
    );


    attachmentGR.orderByDesc(
        'sys_created_on'
    );


    attachmentGR.setLimit(1);

    attachmentGR.query();


    if (attachmentGR.next()) {

        data.student.resume_available =
            true;

        data.student.resume_name =
            attachmentGR.getValue(
                'file_name'
            );

        data.student.resume_url =
            '/sys_attachment.do?sys_id=' +
            attachmentGR.getUniqueValue();

    }


    // =====================================================
    // APPLICATION INFORMATION
    // =====================================================

    data.student.application_count = 0;

    var applicationGR =
        new GlideRecord(
            'x_snc_campus360_student_application'
        );


    applicationGR.addQuery(
        'student',
        studentSysId
    );


    applicationGR.addQuery(
        'opportunity.company',
        companySysId
    );


    applicationGR.orderByDesc(
        'sys_created_on'
    );


    applicationGR.query();


    data.student.applications = [];


    while (applicationGR.next()) {

        var application = {};


        application.application_id =
            applicationGR.getValue(
                'application_id'
            );


        application.status =
            applicationGR.getDisplayValue(
                'application_status'
            );


        application.applied_date =
            applicationGR.getDisplayValue(
                'applied_date'
            );


        if (applicationGR.opportunity) {

            var opportunityGR =
                applicationGR.opportunity.getRefRecord();


            if (
                opportunityGR &&
                opportunityGR.isValidRecord()
            ) {

                application.opportunity_title =
                    opportunityGR.getValue(
                        'opportunity_title'
                    );


                application.opportunity_id =
                    opportunityGR.getValue(
                        'opportunity_id'
                    );

            }

        }


        data.student.applications.push(
            application
        );


        data.student.application_count++;

    }


})();
